import { MinHeap } from './heap.mjs';

export function comparePaths(p, q) {
  const n = Math.min(p.length, q.length);
  for (let i = 0; i < n; i++) {
    if (p[i] < q[i]) return -1;
    if (p[i] > q[i]) return 1;
  }
  return p.length - q.length;
}

function adjacency(edges) {
  if (!Array.isArray(edges)) throw new TypeError('edges deve ser um array');
  const adj = new Map();
  for (const e of edges) {
    if (e === null || typeof e !== 'object' || typeof e.from !== 'string' || typeof e.to !== 'string') throw new TypeError('aresta inválida');
    if (typeof e.w !== 'number' || !Number.isFinite(e.w) || e.w < 0) throw new RangeError(`peso inválido: ${e.w}`);
    if (!adj.has(e.from)) adj.set(e.from, []);
    adj.get(e.from).push({ to: e.to, w: e.w });
  }
  return adj;
}

// Ordem total dos rótulos: custo, depois nº de arestas, depois sequência de nós.
function cmpLabel(x, y) {
  return x.c - y.c || x.p.length - y.p.length || comparePaths(x.p, y.p);
}

function run(edges, source) {
  if (typeof source !== 'string') throw new TypeError('source deve ser string');
  const adj = adjacency(edges);
  const best = new Map([[source, { c: 0, p: [source] }]]);
  const done = new Map();
  const heap = new MinHeap(cmpLabel, [{ c: 0, p: [source] }]);
  while (heap.size) {
    const L = heap.pop();
    const u = L.p[L.p.length - 1];
    if (done.has(u)) continue;
    done.set(u, L);
    for (const { to: v, w } of adj.get(u) ?? []) {
      if (done.has(v)) continue;
      const N = { c: L.c + w, p: [...L.p, v] };
      const old = best.get(v);
      if (old === undefined || cmpLabel(N, old) < 0) {
        best.set(v, N);
        heap.push(N);
      }
    }
  }
  return done;
}

export function shortestPath(edges, source, target) {
  if (typeof target !== 'string') throw new TypeError('target deve ser string');
  const done = run(edges, source);
  const L = done.get(target);
  if (!L) return null;
  return { cost: L.c, path: L.p };
}

export function distances(edges, source) {
  const done = run(edges, source);
  return Object.fromEntries([...done].map(([k, L]) => [k, L.c]));
}

